// 束を ASSISTANT_SCENES へ合流させる。二重に合流しないよう、済んだ束は覚えておく
//   lines      … { 場面キー: [ …セリフ… ] } を通常のセリフへ足す
//   conditions … { 場面キー: { 条件キー: [ …セリフ… ] } } を条件つきのセリフへ足す
//   assistantId… その束が誰のセリフか(省略するとみゅあ)
// ---------- あつ・全画面の基本セリフ(2026-10-22) ----------
// 5人目の助手(隠し助手)。みゅあ・きき・ももすけの仲良し度がそろうと、専用のお話のあとで選べるようになる
// (ASSISTANT_UNLOCK_STORIES・ASSISTANT_ATSU_UNLOCK_BONDS)。公開の印 assistantAtsu が立つまでは選べない。
//
// 【人柄】(2026-10-22 社長の決定)
//   ・勇者・リーダー格。昔からゲームでは勇者をやりたがるタイプで、ギルドでもまとめ役
//   ・上の難易度が好き。モンビーは HELL 推し。「上いこうぜ」が口ぐせ
//   ・Sっ気が強いが、人をよく見ていて心情を察する。茶化したあと、相手が本当に困っていたらすぐ察して引く
//     ★「S」「ドS」とは口に出して言わない・まわりにも言わせない(2026-10-22 社長「遠回しにいって」)。からかい方でにじませる
//   ・ヤンキー思考。仲間は守る・筋を通す・「上等」「かかってこい」。ただし乱暴な言葉や脅しは書かない
//   ・下ネタは言わない(ドラの冗談には乗らず、軽く流すかツッコむ)
//
// 【口調】
//   ・一人称は「俺」。ときどき「オレ」(勢いがあるとき)。「僕」「私」「おで」は使わない
//   ・短く率直。結論を先に一言(「とりあえず○○でいいよ」)。説明は1〜2文で切る
//   ・くだけた言葉。です・ますはほぼ使わない。「〜して」「〜でいいよ」「〜じゃない？」「とりあえず」「てか」
//     「まじで」「やっぱ」「いいね」「〜笑」
//   ・モンヒロビートは「モンビー」
//   ・★遊ぶ人の腕はけなさない。厳しいのは釣り合い(編成のかたより・準備不足)と見た目の話だけ。
//     負けた人には、まず「いい挑戦だった」側から入る
