//
//   e,t   … 表情とセリフ。t の {name} はそのときの呼び方に置き換わる
//   title … 吹き出しの小見出し
//   spot  … 光らせる場所のキー(曲えらび画面の rhythmTutorialSpotClass と対応)
//   help  … 'カテゴリid/項目id'。「この話をヘルプで詳しく見る」が出る
//
// 【並べ方】曲をえらぶ → 難易度をえらぶ → 遊び方 → まわりの機能、の順。
