// ---------- タクティクスバトルのれんしゅう(2026-09-21 ユーザー依頼・デバッグからだけ) ----------
// タクティクスは公開前なので、この台本はデバッグ設定からしか開けない。
// クラシックの本体(BODY)は使い回さず、専用に書いてある。盤面の持ち方が違うので、
