// 教える順(クラシックの練習と同じ骨格に、このモードならではのものを足した):
//   1体ずつのライフとガッツ → 画面の見かた → 敵の狙いの予告 → ガード →
//   連撃(ガードは1ヒットぶん) → アシストカード → 緊急回復と敵の移動 →
//   距離技 → 攻撃 → 技変更 → 固有技
